--
-- Name: faculty; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.faculty (
    fac_id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    fac_usr_id uuid NOT NULL,
    fac_college_id uuid NOT NULL,
    fac_first_name character varying(100) NOT NULL,
    fac_middle_name character varying(100),
    fac_last_name character varying(100) NOT NULL,
    fac_suffix character varying(10),
    fac_phone_number character varying(20) NOT NULL,
    fac_gmail character varying(255),
    fac_address character varying(255),
    fac_employment_type character varying(20) NOT NULL,
    fac_rank character varying(100),
    fac_profile_image text,
    fac_created_at timestamp with time zone DEFAULT now() NOT NULL,
    fac_updated_at timestamp with time zone DEFAULT now() NOT NULL,
    fac_dept_id uuid,
    fac_employee_id character varying(50),
    fac_gender character varying(50),
    fac_civil_status character varying(50),
    fac_dob date,
    fac_nationality character varying(100),
    fac_bio text,
    fac_special_position text,
    fac_special_position_max_hours numeric(5,2),
    fac_bachelors_degree character varying(255),
    fac_masters_degree character varying(255),
    fac_doctorate_degree character varying(255),
    fac_bachelors_abbr character varying(40),
    fac_masters_abbr character varying(40),
    fac_doctorate_abbr character varying(60),
    fac_is_placeholder boolean DEFAULT false NOT NULL,
    CONSTRAINT faculty_fac_employment_type_check CHECK (((fac_employment_type)::text = ANY (ARRAY[('full_time'::character varying)::text, ('part_time'::character varying)::text]))),
    CONSTRAINT faculty_special_position_cap_check CHECK ((((fac_special_position IS NULL) AND (fac_special_position_max_hours IS NULL)) OR ((fac_special_position IS NOT NULL) AND (fac_special_position_max_hours IS NOT NULL) AND
CASE fac_special_position
    WHEN 'Vice-President'::text THEN (fac_special_position_max_hours = (3)::numeric)
    WHEN 'University Director'::text THEN (fac_special_position_max_hours = (6)::numeric)
    WHEN 'Campus Director'::text THEN (fac_special_position_max_hours = (6)::numeric)
    WHEN 'UD Data Protection Officer'::text THEN (fac_special_position_max_hours = (6)::numeric)
    WHEN 'Assistant Campus Director'::text THEN (fac_special_position_max_hours = (9)::numeric)
    WHEN 'Dean of Instruction'::text THEN (fac_special_position_max_hours = (9)::numeric)
    WHEN 'College Dean'::text THEN (fac_special_position_max_hours = (9)::numeric)
    WHEN 'Associate College Dean'::text THEN (fac_special_position_max_hours = (12)::numeric)
    WHEN 'Department Chairperson'::text THEN (fac_special_position_max_hours = (16)::numeric)
    WHEN 'PERG Chair'::text THEN (fac_special_position_max_hours = (16)::numeric)
    WHEN 'Campus Secretary'::text THEN (fac_special_position_max_hours = (16)::numeric)
    WHEN 'College Secretary'::text THEN (fac_special_position_max_hours = (16)::numeric)
    WHEN 'Research Chair'::text THEN (fac_special_position_max_hours = (16)::numeric)
    WHEN 'MIS Officer'::text THEN (fac_special_position_max_hours = (30)::numeric)
    ELSE false
END)))
);


